SELECT id, start_date, status, AVG(monthly_fee) OVER (PARTITION BY customer_id ORDER BY start_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) last3_avg_monthly_fee, MIN(monthly_fee) OVER (PARTITION BY customer_id ORDER BY start_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) last3_min_monthly_fee, SUM(monthly_fee) OVER (PARTITION BY customer_id ORDER BY start_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) last3_sum_monthly_fee FROM subscriptions;
